import pandas as pd
raw = ["12", "", "bad", "0"]
def parse_int(value):
    try:
        return int(value)
    except (TypeError, ValueError):
        return None
result = pd.DataFrame({"raw": raw, "parsed": [parse_int(v) for v in raw]})
result

import pandas as pd
rows = [{"id": 1, "version": 1}, {"id": 1, "version": 2}, {"id": 2, "version": 1}]
latest = {}
for row in rows:
    if row["id"] not in latest or row["version"] > latest[row["id"]]["version"]:
        latest[row["id"]] = row
assert latest[1]["version"] == 2
result = pd.DataFrame(latest.values())
result

from decimal import Decimal, InvalidOperation

def parse_amount(text: str) -> int:
    """'12.34' -> 1234 cents; at most two decimals."""
    try:
        value = Decimal(text.strip())
    except InvalidOperation as exc:
        raise ValueError(f"not an amount: {text!r}") from exc
    if not value.is_finite() or value.as_tuple().exponent < -2:
        raise ValueError(f"not an amount: {text!r}")
    return int(value * 100)

cases = [("12.34", 1234), (" 5 ", 500), ("-0.5", -50)]
results = [{"text": t, "expected": str(e), "actual": str(parse_amount(t))} for t, e in cases]
for bad in ["", "abc", "1.234"]:
    try:
        results.append({"text": bad, "expected": "ValueError", "actual": str(parse_amount(bad))})
    except ValueError:
        results.append({"text": bad, "expected": "ValueError", "actual": "ValueError"})
display(results)
